import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.CZqXuAiL.js";const g=JSON.parse('{"title":"Quick Start","description":"Get Firewall-Plus protecting your first Pterodactyl server in under five minutes.","frontmatter":{"title":"Quick Start","description":"Get Firewall-Plus protecting your first Pterodactyl server in under five minutes."},"headers":[],"relativePath":"firewall-plus/getting-started/quick-start.md","filePath":"firewall-plus/getting-started/quick-start.md","lastUpdated":null}'),l={name:"firewall-plus/getting-started/quick-start.md"};function n(r,e,o,h,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Assumes the panel extension is installed, the node daemon is running on your Wings host, and the scheduler cron + queue worker are active. If not, start with <a href="./installation">Installation</a>.</p><h2 id="_1-add-the-node-admin" tabindex="-1">1. Add the node (admin) <a class="header-anchor" href="#_1-add-the-node-admin" aria-label="Permalink to &quot;1. Add the node (admin)&quot;">​</a></h2><ol><li>On the Wings host, grab the token: <code>sudo cat /etc/firewall-plus/token</code></li><li>Panel → <strong>Admin → Firewall → Nodes → Add Node</strong></li><li>Select the Wings node, enter the FQDN (<strong>plain HTTP</strong> — do not enable HTTPS for the firewall port), paste the token</li><li>Wait for the health check — the node shows <strong>ONLINE</strong> with its version</li></ol><h2 id="_2-enable-firewall-plus-on-a-server-server-owner" tabindex="-1">2. Enable Firewall-Plus on a server (server owner) <a class="header-anchor" href="#_2-enable-firewall-plus-on-a-server-server-owner" aria-label="Permalink to &quot;2. Enable Firewall-Plus on a server (server owner)&quot;">​</a></h2><ol><li>Open the server → <strong>Firewall</strong> tab</li><li>Toggle <strong>Firewall-Plus for this server</strong> on</li><li>Accept the Terms of Service (required before any mutation)</li></ol><p>Rules are never pushed to a node until this per-server toggle is on. Turning it off queues a flush of that server&#39;s chains.</p><h2 id="_3-add-rules-and-apply" tabindex="-1">3. Add rules and apply <a class="header-anchor" href="#_3-add-rules-and-apply" aria-label="Permalink to &quot;3. Add rules and apply&quot;">​</a></h2><ol><li>In the <strong>Rules</strong> tab, add a rule — e.g. a <strong>SYN limit</strong> scoped to your game port, or pick a <strong>game preset</strong> from the Presets tab</li><li>Optionally add trusted IPs to the <strong>Whitelist</strong> or attackers to the <strong>Blacklist</strong></li><li>Click <strong>Apply firewall</strong></li></ol><p>The apply is queued (<code>ApplyFirewallRulesJob</code>), sent to the node, and applied atomically via <code>iptables-restore</code> with a snapshot + automatic rollback. The UI polls apply status until it lands.</p><h2 id="_4-verify-on-the-node-optional-root" tabindex="-1">4. Verify on the node (optional, root) <a class="header-anchor" href="#_4-verify-on-the-node-optional-root" aria-label="Permalink to &quot;4. Verify on the node (optional, root)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FWP-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">serverI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FWP-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">serverI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">por</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # per-port scoped rules</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fwp-wl-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">serverI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="_5-optional-enable-smart-detection" tabindex="-1">5. (Optional) Enable SMART detection <a class="header-anchor" href="#_5-optional-enable-smart-detection" aria-label="Permalink to &quot;5. (Optional) Enable SMART detection&quot;">​</a></h2><p>SMART must be <strong>granted per server by an admin</strong> first:</p><ol><li>Admin → <strong>Firewall → Servers</strong> → grant <strong>SMART mode</strong> for the server</li><li>Server owner: <strong>Firewall → SMART tab</strong> → enable SMART mode, optionally set a Discord webhook</li><li>Re-apply the firewall — the apply payload now carries <code>smart.enabled: true</code></li></ol><p>The node starts its EWMA monitor; on anomaly it escalates L1→L3 mitigations with cooldowns, logs the attack event, and notifies the owner via Discord webhook and email (if the admin enabled owner email alerts).</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="./../user-guide/rules">Rule Types</a> — what each of the 13 rule types actually does</li><li><a href="./../configuration/reference">Configuration Reference</a> — node config, env vars, admin settings</li><li><a href="./../user-guide/cli">CLI Reference</a> — artisan commands and node scripts</li></ul>`,18)])])}const c=a(l,[["render",n]]);export{g as __pageData,c as default};
